<script setup lang="ts">import{computed,onBeforeUnmount,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{Clock,Lightning,Location,Wallet}from'@element-plus/icons-vue';const route=useRoute(),router=useRouter(),total=Number(route.query.duration||60)*60,elapsed=ref(0),timer=window.setInterval(()=>{if(elapsed.value<total)elapsed.value++},1000);onBeforeUnmount(()=>clearInterval(timer));const percent=computed(()=>Math.min(100,Math.round(elapsed.value/total*100))),remaining=computed(()=>Math.ceil((total-elapsed.value)/60)),cost=computed(()=>elapsed.value/3600*.5);const time=computed(()=>`${String(Math.floor(elapsed.value/60)).padStart(2,'0')}:${String(elapsed.value%60).padStart(2,'0')}`)</script>
<template><div class="charge-page"><main class="charge-wrap"><header><span class="live"><i/>充电进行中</span><h1>充电状态</h1><p><Location/>{{route.query.location||'校园充电区'}} · 充电桩 #{{route.params.id}}</p></header><section class="charge-card"><div class="ring" :style="{'--progress':`${percent*3.6}deg`}"><div><Lightning/><strong>{{percent}}%</strong><small>已完成</small></div></div><div class="charge-info"><h2>本次充电</h2><p>设备运行正常，请在充电完成后及时移走车辆。</p><div class="metrics"><article><Clock/><div><small>已充时长</small><strong>{{time}}</strong></div></article><article><Clock/><div><small>预计剩余</small><strong>{{remaining}} 分钟</strong></div></article><article><Wallet/><div><small>当前费用</small><strong>¥{{cost.toFixed(2)}}</strong></div></article></div><el-progress :percentage="percent" :show-text="false" :stroke-width="8"/><el-button size="large" @click="router.push('/user-dashboard')">返回首页</el-button></div></section></main></div></template>
<style scoped>.charge-page{min-height:calc(100vh - 72px);display:grid;place-items:center;padding:48px 20px;background:#f4f7f4}.charge-wrap{width:min(900px,100%)}header{text-align:center;margin-bottom:25px}.live{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;color:var(--success);background:var(--brand-soft);border-radius:99px;font-size:11px;font-weight:750}.live i{width:7px;height:7px;background:currentColor;border-radius:50%}header h1{margin:16px 0 8px;font-size:35px}header p{display:flex;justify-content:center;align-items:center;gap:5px;margin:0;color:var(--text-muted);font-size:12px}header p :deep(svg){width:14px}.charge-card{display:grid;grid-template-columns:300px 1fr;align-items:center;gap:40px;padding:44px;background:#fff;border:1px solid var(--border-color);border-radius:24px;box-shadow:var(--shadow-md)}.ring{width:230px;height:230px;margin:auto;display:grid;place-items:center;background:conic-gradient(var(--brand) var(--progress),#e9eeea 0);border-radius:50%}.ring>div{width:190px;height:190px;display:grid;place-content:center;text-align:center;background:#fff;border-radius:50%}.ring :deep(svg){width:30px;margin:auto;color:var(--brand)}.ring strong{margin-top:7px;font-size:38px}.ring small{color:var(--text-muted)}.charge-info h2,.charge-info>p{margin:0}.charge-info h2{font-size:23px}.charge-info>p{margin:8px 0 25px;color:var(--text-secondary);font-size:12px;line-height:1.6}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:24px}.metrics article{padding:13px;background:var(--surface-muted);border-radius:11px}.metrics article>:deep(svg){width:17px;color:var(--brand)}.metrics small,.metrics strong{display:block}.metrics small{margin-top:7px;color:var(--text-muted);font-size:9px}.metrics strong{margin-top:4px;font-size:12px}.charge-info>.el-button{width:100%;margin-top:24px}@media(max-width:720px){.charge-card{grid-template-columns:1fr;padding:28px 18px}.ring{width:190px;height:190px}.ring>div{width:158px;height:158px}.metrics{grid-template-columns:1fr}}
</style>
